CREATE TABLE IF NOT EXISTS telegram_links(customer_id TEXT PRIMARY KEY REFERENCES customers(id),user_id TEXT NOT NULL UNIQUE,chat_id TEXT NOT NULL UNIQUE,generation TEXT NOT NULL,created_at INTEGER NOT NULL,blocked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS telegram_link_tokens(token_hash TEXT PRIMARY KEY,customer_id TEXT NOT NULL,expires_at INTEGER NOT NULL,user_id TEXT,chat_id TEXT,display_name TEXT,claimed_at INTEGER);
CREATE TABLE IF NOT EXISTS telegram_updates(update_id INTEGER PRIMARY KEY,payload_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,lease_until INTEGER,attempts INTEGER NOT NULL DEFAULT 0,error_class TEXT);
CREATE TABLE IF NOT EXISTS telegram_callbacks(token_hash TEXT PRIMARY KEY,customer_id TEXT NOT NULL,generation TEXT NOT NULL,action TEXT NOT NULL,resource TEXT,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE IF NOT EXISTS telegram_conversations(customer_id TEXT PRIMARY KEY,generation TEXT NOT NULL,step TEXT NOT NULL,payload_json TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS secure_actions(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,generation TEXT,kind TEXT NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',resource_id TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verified_accounts(customer_id TEXT PRIMARY KEY,bank_name TEXT NOT NULL,account_number TEXT NOT NULL,account_holder TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',updated_at INTEGER NOT NULL,verified_by TEXT,verified_at INTEGER);
CREATE TABLE IF NOT EXISTS notification_events(event_key TEXT PRIMARY KEY,customer_id TEXT NOT NULL,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_deliveries(id INTEGER PRIMARY KEY,event_key TEXT UNIQUE,customer_id TEXT,chat_id TEXT NOT NULL,generation TEXT,method TEXT NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,lease_until INTEGER,lease_token TEXT,sent_at INTEGER,message_id INTEGER,error_class TEXT,ticket_id TEXT,support_message_id INTEGER);
CREATE INDEX IF NOT EXISTS telegram_delivery_due ON telegram_deliveries(state,available_at);
CREATE TABLE IF NOT EXISTS notification_preferences(customer_id TEXT PRIMARY KEY,payments INTEGER NOT NULL DEFAULT 1,withdrawals INTEGER NOT NULL DEFAULT 1,support INTEGER NOT NULL DEFAULT 1,security INTEGER NOT NULL DEFAULT 1,digest TEXT NOT NULL DEFAULT 'off',quiet_start INTEGER,quiet_end INTEGER,telegram_enabled INTEGER NOT NULL DEFAULT 0,marketing_consent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS scheduler_runs(run_key TEXT PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_runtime(name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS support_tickets(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('OPEN','WAITING_ADMIN','WAITING_CUSTOMER','CLOSED')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS support_messages(id INTEGER PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES support_tickets(id),actor_id TEXT NOT NULL,channel TEXT NOT NULL,body TEXT NOT NULL,internal INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,attachment_name TEXT,attachment_type TEXT,attachment BLOB);
CREATE INDEX IF NOT EXISTS support_ticket_messages ON support_messages(ticket_id,id);
CREATE TABLE IF NOT EXISTS support_telegram_messages(chat_id TEXT NOT NULL,message_id INTEGER NOT NULL,ticket_id TEXT NOT NULL,support_message_id INTEGER NOT NULL,customer_id TEXT NOT NULL,generation TEXT,PRIMARY KEY(chat_id,message_id));
CREATE TABLE IF NOT EXISTS action_audit(id INTEGER PRIMARY KEY,actor_customer_id TEXT NOT NULL,telegram_user_id TEXT,channel TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT,result TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS policy_versions(slug TEXT NOT NULL,version TEXT NOT NULL,title TEXT NOT NULL,content_json TEXT NOT NULL,content_hash TEXT NOT NULL,effective_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(slug,version));
CREATE TRIGGER IF NOT EXISTS policy_no_update BEFORE UPDATE ON policy_versions BEGIN SELECT RAISE(ABORT,'immutable policy version'); END;
CREATE TRIGGER IF NOT EXISTS policy_no_delete BEFORE DELETE ON policy_versions BEGIN SELECT RAISE(ABORT,'immutable policy version'); END;
CREATE TABLE IF NOT EXISTS policy_consents(customer_id TEXT NOT NULL,slug TEXT NOT NULL,version TEXT NOT NULL,accepted_at INTEGER NOT NULL,channel TEXT NOT NULL,PRIMARY KEY(customer_id,slug,version),FOREIGN KEY(slug,version) REFERENCES policy_versions(slug,version));
CREATE TABLE IF NOT EXISTS registration_consents(registration_id TEXT PRIMARY KEY,version TEXT NOT NULL,accepted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payment_checks(payment_id TEXT PRIMARY KEY REFERENCES payments(id),next_check_at INTEGER NOT NULL,lease_until INTEGER);
